const FAQ_WORD_COUNT = UAE_B2B_MR_FAQ.reduce(
  (sum, item) => sum + countWords(item.question) + countWords(item.answer),
  0,
);

export const UAE_B2B_MR_WORD_COUNT =
  countWords(UAE_B2B_MR_EXECUTIVE_SUMMARY_HTML) + countWords(UAE_B2B_MR_BODY_HTML) + FAQ_WORD_COUNT;

const READING_WORDS_PER_MINUTE = 225;

export const UAE_B2B_MR_READING_TIME = Math.ceil(
  (countWords(UAE_B2B_MR_EXECUTIVE_SUMMARY_HTML) + countWords(NARRATIVE_HTML) + FAQ_WORD_COUNT) /
    READING_WORDS_PER_MINUTE,
);

